package com.staging.sg.fraud.gateway.service;
import com.staging.sg.fraud.gateway.crypto.FraudKeyExchangeHsm;import org.jpos.iso.*;import org.jpos.iso.packager.ISO87APackager;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class PermanentIsoKeyClientProcessorTest{@Test void importsTakUnderZmkAndAcknowledgesWithoutClearKey()throws Exception{FraudKeyExchangeHsm hsm=mock(FraudKeyExchangeHsm.class);when(hsm.importTakUnderZmk(anyString(),anyString(),anyString(),anyString())).thenReturn(new FraudKeyExchangeHsm.ImportedTak("hsm:tak:bank-a","A1B2C3"));var p=new PermanentIsoKeyClientProcessor(hsm,"BANK_A","hsm:zmk:bank-a","161","162",96,48);ISOMsg delivery=new ISOMsg();delivery.setPackager(new ISO87APackager());delivery.setMTI("0810");delivery.set(7,"0815031000");delivery.set(11,"000002");delivery.set(70,"161");delivery.set(96,ISOUtil.hex2byte("00112233445566778899AABBCCDDEEFF"));delivery.set(48,"A1B2C3");ISOMsg ack=p.importAndAcknowledge(delivery);verify(hsm).importTakUnderZmk("BANK_A","hsm:zmk:bank-a","00112233445566778899AABBCCDDEEFF","A1B2C3");assertThat(ack.getMTI()).isEqualTo("0800");assertThat(ack.getString(70)).isEqualTo("162");assertThat(ack.hasField(96)).isFalse();}}
